/* Transit Reader event rule: moving significator in a significator's star AND sub. */
(()=>{'use strict';const IDS=['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke'],ORDER=['Ke','Ve','Su','Mo','Ma','Ra','Ju','Sa','Me'],YEARS={Ke:7,Ve:20,Su:6,Mo:10,Ma:7,Ra:18,Ju:16,Sa:19,Me:17};
function plan(selected,significators=IDS){const display=[...new Set(selected)];if(!display.length)throw Error('Select at least one transiting planet.');if(display.some(id=>!IDS.includes(id)))throw Error('Unknown transiting planet.');const supported=new Set(significators),scan=display.filter(id=>supported.has(id));if(!scan.length)throw Error('The selected planets are not event significators. Select a planet from the event significator list.');return {display:scan,scan,excluded:display.filter(id=>!supported.has(id))};}
function tracks(significators,planets=IDS){const selected=new Set(significators),sectors=[];for(let nak=0;nak<27;nak++){let lower=nak*48000;const starLord=ORDER[nak%9];for(let i=0;i<9;i++){const subLord=ORDER[(nak%9+i)%9],upper=lower+48000*YEARS[subLord]/120;if(selected.has(starLord)&&selected.has(subLord))sectors.push({nak,starLord,subLord,lower,upper,...(window.KPDisplay?{nakName:KPDisplay.longitudeDetails(lower+1).nakshatra}:{})});lower=upper;}}return [...new Set(planets)].filter(id=>selected.has(id)).flatMap(planet=>sectors.map(s=>({id:'reader:'+planet+':'+s.nak+':'+s.subLord,planet,label:'Nakshatra '+(s.nakName||s.nak+1)+' ('+s.starLord+') · Sub '+s.subLord,levels:['star','sub'],sector:s,test:p=>p.nakIndex===s.nak&&p.stl===s.starLord&&p.sl===s.subLord})));}
window.KPTransitEventDetail=Object.freeze({plan,tracks,ids:IDS});})();
